{#- Copies: same rules as "Sales Invoice Multi Copy Master" — draft → DRAFT COPY; ?print_all=1 → four
    copies; ?copy_name=… → that copy; else Original. -#}
{%- set print_all_val = frappe.form_dict.get('print_all') | string -%}
{%- set copy_param = frappe.form_dict.get('copy_name') -%}
{%- if doc.docstatus == 0 -%}{%- set copy_list = ["DRAFT COPY"] -%}
{%- elif print_all_val == "1" -%}{%- set copy_list = ["Original", "Duplicate", "Triplicate", "Quadruplicate"] -%}
{%- elif copy_param -%}{%- set copy_list = [copy_param] -%}
{%- else -%}{%- set copy_list = ["Original"] -%}{%- endif -%}
{%- set ns = namespace(line_discount=0.0) -%}
{%- for item in doc.items -%}{%- set ns.line_discount = ns.line_discount + ((item.discount_amount or 0) | float | abs) * ((item.qty or 0) | float | abs) -%}{%- endfor -%}
{%- set overall_discount = (doc.discount_amount or 0) | float | abs -%}
{%- set total_abs = (doc.rounded_total or doc.grand_total or 0) | float | abs -%}
{%- set fmt = "{:,.2f}" -%}
{%- macro money(v) -%}{{ frappe.utils.fmt_money((v or 0) | float | abs, currency=doc.currency) }}{%- endmacro -%}
{%- set words = frappe.utils.money_in_words(total_abs, "INR") | replace("INR ", "") | replace(" only.", "") | replace(" Only.", "") -%}
{%- set remarks = (doc.remarks or "") | trim -%}
{%- if remarks in ("No Remarks", "No remarks") -%}{%- set remarks = "" -%}{%- endif -%}
<style>
  .rn-copy { page-break-after: always; font-family: Arial, sans-serif; color: #000; }
  .rn-copy:last-child { page-break-after: auto; }
  .rn-letterhead { width: 100%; margin-bottom: 2px; }
  .rn-head { position: relative; width: 100%; text-align: center; padding-top: 1px; margin-bottom: 4px; }
  .rn-title { font-size: 10pt; font-weight: bold; letter-spacing: .5px; }
  .rn-sub { font-size: 8pt; line-height: 1.35; }
  .rn-hsn { margin-top: 3px; font-size: 7.5pt; }
  .rn-hsn table { width: 100% !important; }
  .rn-chip { position: absolute; top: 0; right: 0; border: 2px solid #000; width: 135px; padding: 5px; font-weight: bold;
             font-size: 11px; text-transform: uppercase; background: #fff; text-align: center; }
  .rn-box { width: 100%; border-collapse: collapse; border: 1.2px solid #000; font-size: 7.5pt; line-height: 1.15; table-layout: fixed; }
  .rn-box td { vertical-align: top; }
  .rn-left { width: 50%; padding: 3px 4px; border-right: 1.2px solid #000; }
  .rn-party { font-weight: bold; font-size: 10pt; text-transform: uppercase; margin-bottom: 1px; }
  .rn-grid { width: 100%; border-collapse: collapse; table-layout: fixed; }
  .rn-grid td { padding: 2px 4px; vertical-align: top; }
  .rn-grid .l { font-weight: bold; width: 38%; white-space: nowrap; }
  .rn-hl { background: #f2f2f2; }
  .rn-items { width: 100%; border-collapse: collapse; font-size: 7.5pt; margin-top: 4px; table-layout: fixed; }
  .rn-items th { border: 1px solid #000; background: #f2f2f2; padding: 3px; font-weight: bold; }
  .rn-items td { border-left: 1px solid #000; border-right: 1px solid #000; padding: 2px 3px; vertical-align: top; }
  .rn-items tr:last-child td { border-bottom: 1px solid #000; }
  .rn-r { text-align: right; } .rn-c { text-align: center; }
  .rn-sum { width: 100%; border-collapse: collapse; font-size: 8pt; margin-top: 3px; }
  .rn-sum td { padding: 1px 2px; }
  .rn-total td { background: #f2f2f2; border: 1px solid #000; font-weight: bold; font-size: 9pt; }
  .rn-words { border: 1px solid #000; padding: 3px 6px; background: #fafafa; font-size: 8pt; margin-top: 4px; }
  .rn-foot { width: 100%; border: 1px solid #000; border-top: none; border-collapse: collapse; table-layout: fixed; }
  .rn-reason { border: 1px solid #000; border-top: none; padding: 4px 6px; font-size: 8pt; }
  .rn-note { font-size: 7.5pt; margin-top: 3px; }
</style>
{#- Debit Note — a Purchase Invoice return (is_return), issued to the supplier. Layout follows
    "Sales invoice Print Format 4"; amounts print positive; the supplier's original bill and the
    reason (Remarks) are shown as GST requires. -#}
{%- set orig = frappe.db.get_value("Purchase Invoice", doc.return_against, ["posting_date", "bill_no", "bill_date"], as_dict=1) if doc.return_against else None -%}
{%- for copy_label in copy_list %}
<div class="rn-copy">
  {#- The company header (Letter Head), as "Sales invoice Print Format 4" gets it — on every copy. -#}
  {% if letter_head and not no_letterhead %}<div class="rn-letterhead">{{ letter_head }}</div>{% endif %}
  <div class="rn-head">
    <div class="rn-title">DEBIT NOTE</div>
    <div class="rn-sub">No: <strong>{{ doc.name }}</strong> | Date: <strong>{{ frappe.utils.formatdate(doc.posting_date, "dd-MMM-yyyy") }}</strong>
      {%- if orig and orig.bill_no %}<br>Against Your Bill: <strong>{{ orig.bill_no }}</strong>{% if orig.bill_date %} dt. <strong>{{ frappe.utils.formatdate(orig.bill_date, "dd-MMM-yyyy") }}</strong>{% endif %}{% endif %}</div>
    <div class="rn-chip">{{ copy_label }}</div>
  </div>

  <table class="rn-box"><tr>
    <td class="rn-left">
      <div style="font-size:7pt;font-weight:bold;color:#444;">TO (SUPPLIER)</div>
      <div class="rn-party">M/s. {{ doc.supplier_name }}</div>
      <div style="font-size:8.5pt;line-height:1.05;">{{ doc.address_display or "" }}</div>
      {% if doc.supplier_gstin %}<div style="margin-top:3px;"><strong>G.S.T. : </strong>{{ doc.supplier_gstin }}</div>{% endif %}
      {% if doc.place_of_supply %}<div><strong>Place of Supply : </strong>{{ doc.place_of_supply }}</div>{% endif %}
    </td>
    <td style="width:50%;padding:0;">
      <table class="rn-grid">
        <tr class="rn-hl"><td class="l">Your Bill No.</td><td>: <strong>{{ (orig.bill_no if orig else "") or doc.bill_no or "" }}</strong></td></tr>
        <tr><td class="l">Your Bill Date</td><td>: {{ frappe.utils.formatdate(orig.bill_date) if orig and orig.bill_date else (frappe.utils.formatdate(doc.bill_date) if doc.bill_date else "") }}</td></tr>
        <tr><td class="l">Our Ref. (Purchase Inv.)</td><td>: {{ doc.return_against or "— (direct debit note)" }}{% if orig %} dt. {{ frappe.utils.formatdate(orig.posting_date) }}{% endif %}</td></tr>
        {% if doc.company_gstin %}<tr><td class="l">Our GSTIN</td><td>: {{ doc.company_gstin }}</td></tr>{% endif %}
        <tr><td class="l">Type</td><td>: Purchase return / debit to supplier</td></tr>
      </table>
    </td>
  </tr></table>

  <table class="rn-items">
    <thead><tr>
      <th style="width:5%;">#</th><th style="width:38%;text-align:left;">Item returned</th><th style="width:10%;">HSN</th>
      <th style="width:11%;">Qty</th><th style="width:10%;">Disc.</th><th style="width:12%;">Rate</th><th style="width:14%;">Amount</th>
    </tr></thead>
    <tbody>
    {% for item in doc.items %}
      <tr>
        <td class="rn-c">{{ loop.index }}</td>
        <td>{{ item.item_name }}{% if item.item_name != item.item_code %}<div style="font-size:6.5pt;color:#444;">{{ item.item_code }}</div>{% endif %}</td>
        <td class="rn-c">{{ item.gst_hsn_code or "" }}</td>
        <td class="rn-r">{{ "{:g}".format((item.qty or 0) | float | abs) }} {{ item.uom or "" }}</td>
        <td class="rn-r">{{ money(item.discount_amount) if item.discount_amount else "" }}</td>
        <td class="rn-r">{{ money(item.rate) }}</td>
        <td class="rn-r">{{ money(item.amount) }}</td>
      </tr>
    {% endfor %}
    </tbody>
  </table>

  <table class="rn-sum"><tr>
    <td style="width:62%;vertical-align:bottom;">
      <div style="font-weight:bold;">Total Qty returned: {{ "{:g}".format((doc.total_qty or 0) | float | abs) }}</div>
      {% if doc.gst_breakup_table %}<div class="rn-hsn">{{ doc.gst_breakup_table }}</div>{% endif %}
    </td>
    <td style="width:38%;padding-left:10px;">
      <table style="width:100%;border-collapse:collapse;">
        <tr><td>Gross Total</td><td class="rn-r">{{ fmt.format(((doc.net_total or 0) | float | abs) + ns.line_discount + overall_discount) }}</td></tr>
        {% if ns.line_discount > 0.01 %}<tr><td>Line-wise Discount (-)</td><td class="rn-r">- {{ fmt.format(ns.line_discount) }}</td></tr>{% endif %}
        {% if overall_discount > 0.01 %}<tr><td>Overall Discount (-)</td><td class="rn-r">- {{ fmt.format(overall_discount) }}</td></tr>{% endif %}
        <tr style="border-top:0.5px solid #ccc;font-weight:bold;"><td>Taxable Value</td><td class="rn-r">{{ fmt.format((doc.net_total or 0) | float | abs) }}</td></tr>
        {% for tax in doc.taxes %}{% if tax.tax_amount and ((tax.tax_amount | float | abs) > 0.01) %}
        <tr><td>{{ tax.account_head.split(' - ')[0] }}</td><td class="rn-r">{{ fmt.format(tax.tax_amount | float | abs) }}</td></tr>
        {% endif %}{% endfor %}
        {% if doc.rounding_adjustment and ((doc.rounding_adjustment | float | abs) > 0.001) %}<tr><td>Round Off</td><td class="rn-r">{{ fmt.format(doc.rounding_adjustment | float | abs) }}</td></tr>{% endif %}
        <tr class="rn-total"><td>DEBIT TOTAL ₹</td><td class="rn-r">{{ fmt.format(total_abs) }}</td></tr>
      </table>
    </td>
  </tr></table>

  <div class="rn-words"><strong>Amount in Words:</strong> <span style="font-style:italic;font-weight:bold;">Rupees {{ words }} Only</span>
    <div class="rn-note">
      {% if orig and orig.bill_no %}We have debited your account by ₹ {{ fmt.format(total_abs) }} against your Bill <strong>{{ orig.bill_no }}</strong> for the goods returned.
      {% else %}We have debited your account by ₹ {{ fmt.format(total_abs) }} for the goods returned.{% endif %}
    </div>
  </div>
  {#- No Terms & Conditions here: an invoice's terms ("goods once sold…") contradict a return. -#}
  <table class="rn-foot"><tr>
    <td style="width:70%;font-size:8pt;border-right:1px solid #000;padding:4px 6px;vertical-align:top;">
      <div style="font-weight:bold;text-decoration:underline;margin-bottom:2px;">Reason / Remarks</div>
      <div style="white-space:pre-wrap;">{{ remarks or "—" }}</div>
    </td>
    <td style="width:30%;text-align:center;padding:8px 4px 4px;vertical-align:top;">
      <div style="font-size:8pt;font-weight:bold;">For {{ doc.company }}</div><br><br><br><br>
      <div style="display:inline-block;border-top:1px solid #000;padding-top:2px;width:90%;font-weight:bold;font-size:8pt;">Authorised Signatory</div>
    </td>
  </tr></table>
</div>
{%- endfor %}
